// nenwa: generated by `nenwa install`. `nenwa setup --remove` deletes this file.
// Pi has no MCP, so this extension gives it the nenwa tools, tells the nenwa daemon about this
// conversation, and puts messages that arrive for it into the conversation.
import { spawn } from "node:child_process";
import { Type } from "typebox";

const NENWA = __NENWA_EXE__;

// Runs nenwa with the given stdin and returns its stdout. `started` receives the child (to stop a long wait).
function run(args: string[], stdin: string, started?: (p: any) => void): Promise<string> {
  return new Promise((resolve) => {
    let out = "";
    let p: any;
    try {
      p = spawn(NENWA, args, { stdio: ["pipe", "pipe", "ignore"], windowsHide: true });
    } catch {
      return resolve("");
    }
    started?.(p);
    p.stdout.on("data", (d: any) => (out += d));
    p.on("error", () => resolve(""));
    p.on("close", () => resolve(out));
    p.stdin.on("error", () => {});
    p.stdin.end(stdin);
  });
}

async function hook(event: string, input: object, started?: (p: any) => void): Promise<string> {
  try {
    const text = JSON.parse(await run(["hook", "pi", event], JSON.stringify(input), started)).text;
    return typeof text === "string" ? text : "";
  } catch {
    return "";
  }
}

// The tools are the ones of `nenwa mcp`; each call asks a short-lived MCP server.
async function call(tool: string, args: object): Promise<string> {
  const lines = [
    { jsonrpc: "2.0", id: 1, method: "initialize", params: {} },
    { jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: tool, arguments: args } },
  ];
  const out = await run(["mcp", "--agent", "pi"], lines.map((l) => JSON.stringify(l)).join("\n") + "\n");
  for (const line of out.split("\n")) {
    try {
      const r = JSON.parse(line);
      if (r.id !== 2) continue;
      if (r.error) return `nenwa error: ${r.error.message}`;
      return (r.result?.content ?? []).map((c: any) => c.text ?? "").join("\n");
    } catch {}
  }
  return "nenwa did not answer. Is the nenwa daemon running? (run `nenwa who` in a terminal)";
}

export default function (pi: any) {
  let current: { session_id: string; cwd: string } | null = null;
  let waiting: any = null;
  let generation = 0;

  const say = (text: string, options: object) => {
    try {
      pi.sendMessage({ customType: "nenwa", content: text, display: true }, options);
    } catch {}
  };
  const stopWaiting = () => {
    generation++;
    try {
      waiting?.kill();
    } catch {}
    waiting = null;
  };
  // Waits for messages while the conversation is open; an idle conversation starts working when one arrives.
  const listen = async (gen: number) => {
    while (gen === generation && current) {
      const began = Date.now();
      const text = await hook("wait", current, (p) => {
        waiting = p;
        p.unref?.();
      });
      if (text) say(text, { triggerTurn: true, deliverAs: "steer" });
      else if (gen === generation && Date.now() - began < 2000) await new Promise((r) => setTimeout(r, 5000).unref?.());
    }
  };

  pi.on("session_start", async (_event: any, ctx: any) => {
    stopWaiting();
    current = { session_id: String(ctx.sessionManager.getSessionId()), cwd: String(ctx.cwd) };
    const intro = await hook("session-start", current);
    if (intro) say(intro, { deliverAs: "nextTurn" });
    // One-shot runs (-p, --mode json) end by themselves, so they only send.
    if (ctx.mode === "tui" || ctx.mode === "rpc") void listen(generation);
  });
  pi.on("agent_start", async () => {
    if (current) await hook("user-prompt-submit", current);
  });
  pi.on("agent_settled", async () => {
    if (!current) return;
    const text = await hook("stop", current);
    if (text) say(text, { triggerTurn: true, deliverAs: "followUp" });
  });
  pi.on("session_shutdown", async () => {
    stopWaiting();
    if (current) await hook("session-end", current);
    current = null;
  });

  pi.registerTool({
    name: "nenwa_list_team",
    label: "nenwa: list team",
    description:
      "nenwa: list the agents you can message (your own Claude Code, Codex, Cursor and other sessions, on this and your other computers) with their addresses.",
    promptSnippet: "List the agents reachable through nenwa and their addresses",
    parameters: Type.Object({}),
    async execute() {
      return { content: [{ type: "text", text: await call("list_team", {}) }], details: {} };
    },
  });
  pi.registerTool({
    name: "nenwa_send_message",
    label: "nenwa: send message",
    description:
      "nenwa: send a message to another agent. `to` is an address from nenwa_list_team (person/session@machine). When answering a <nenwa-message>, pass its id as reply_to. This is nenwa's send_message.",
    promptSnippet: "Send a message to another agent through nenwa",
    parameters: Type.Object({
      to: Type.String({ description: "Address: person/session@machine" }),
      message: Type.String({ description: "The message text" }),
      reply_to: Type.Optional(Type.String({ description: "id of the <nenwa-message> this answers" })),
    }),
    async execute(_id: string, params: any) {
      return { content: [{ type: "text", text: await call("send_message", params) }], details: {} };
    },
  });
}
